(function () {
  var bubble = null;

  function typeLink(node) {
    var link = node && node.closest ? node.closest("a.api-type-ref, a.api-ref") : null;
    if (!link) return null;
    var href = link.getAttribute("href") || "";
    if (href.indexOf("#type-") < 0) return null;
    return link;
  }

  function membersOf(link) {
    var href = link.getAttribute("href") || "";
    var id = href.split("#")[1] || "";
    try { id = decodeURIComponent(id); } catch (err) {}
    var table = window.TYPE_MEMBERS || {};
    return table[id] || "";
  }

  function place(link) {
    var rect = link.getBoundingClientRect();
    var width = bubble.offsetWidth;
    var height = bubble.offsetHeight;
    var left = rect.left;
    if (left + width > window.innerWidth - 8)
      left = Math.max(8, window.innerWidth - width - 8);
    var top = rect.bottom + 6;
    if (top + height > window.innerHeight - 8 && rect.top - height - 6 > 8)
      top = rect.top - height - 6;
    bubble.style.left = (left + window.scrollX) + "px";
    bubble.style.top = (top + window.scrollY) + "px";
  }

  function show(link, text) {
    if (!bubble) {
      bubble = document.createElement("div");
      bubble.className = "type-hint";
      document.body.appendChild(bubble);
    }
    bubble.textContent = text;
    bubble.style.display = "block";
    place(link);
  }

  function hide() {
    if (bubble) bubble.style.display = "none";
  }

  function open(link) {
    var text = membersOf(link);
    show(link, text || "Members could not be read.");
  }

  document.addEventListener("mouseover", function (event) {
    var link = typeLink(event.target);
    if (link) open(link);
  });
  document.addEventListener("mouseout", function (event) {
    var link = typeLink(event.target);
    if (!link) return;
    if (event.relatedTarget && link.contains(event.relatedTarget)) return;
    hide();
  });
  document.addEventListener("focusin", function (event) {
    var link = typeLink(event.target);
    if (link) open(link);
  });
  document.addEventListener("focusout", hide);
  window.addEventListener("scroll", hide, true);
})();
